ue characteristics of crisis-driven markets. The strategy's success in normal market conditions may be due to its ability to identify trends and momentum, but its failure to adapt to changing market conditions and sentiment may be the primary cause of its underperformance during the COVID stress regime.	[0.011984627,0.034470867,-0.029180245,-0.03825381,0.015805986,0.034795914,-0.010567941,0.010770179,0.017333133,-0.10022422,-0.05037299,0.0592202,-0.003508189,0.0072308676,-0.0033023763,-0.007759194,0.049990226,-0.060671736,-0.0036846,0.025747383,-0.0033267273,0.00045030634,-0.01135406,0.009733798,0.027554361,-0.008641608,0.020141734,-0.01875137,0.034012817,0.24029016,-0.02475869,-0.042768057,-0.0045389906,0.00033374905,-0.0002844479,0.010510137,-0.007784127,-0.0034179112,0.017059872,0.029978035,0.0013619654,0.018592438,0.045948472,0.04243997,0.02129088,-0.020021895,0.006502249,0.017474364,-0.012125684,0.0029181496,-0.019105067,-0.009848342,0.019832917,-0.014683806,0.013842428,0.019745715,-0.0054306597,0.0033785978,0.040655125,-0.013719209,-0.040514987,0.019385783,0.059172556,-0.005496735,0.055168014,-0.00043200873,-0.0080948,0.019490672,0.009681795,-0.04870715,0.020712882,-0.009494249,-0.00905044,-0.01133569,-0.036248658,-0.026714899,-0.031542815,0.04465955,-0.019652711,0.054785468,0.010397936,-0.012470531,-0.031447526,0.01791255,0.0061848983,0.08413103,0.0153579805,0.0138358725,-0.0032664423,-0.017704776,0.028305978,0.0027064355,-0.00045460556,-0.0064680073,-0.029088994,0.0118979765,0.004037713,-0.008530351,-0.017567841,0.05779113,-0.0646085,0.005018481,0.016177416,0.006040263,-0.008031313,0.0033112366,-0.026937962,0.031798106,-0.005133743,0.02761544,-0.02254097,-0.28115293,-0.004453025,-0.022050131,-0.03969171,-0.06366534,0.05604309,0.037782386,-0.012810873,-0.021758031,0.035681386,0.045157224,0.026339138,0.029673498,-0.02369063,0.0007661024,-0.010861131,0.027903888,-0.006526797,-0.027763803,-0.026728706,0.00046143867,0.012548511,-0.057101913,0.036747474,0.03626309